        if(e.getItem().is(AMTagRegistry.PLATYPUS_CHARGEABLES)) {
            superCharged = e.getItem().is(AMTagRegistry.PLATYPUS_SUPER_CHARGEABLES);
            this.setSensing(true);
        }
